import React, { useState } from 'react';
import './VistaProducto.css';

const VistaProducto = () => {
  const [calificacion, setCalificacion] = useState(0);
  const [comentario, setComentario] = useState('');
  const [publicando, setPublicando] = useState(false);

  const manejarPublicacion = () => {
    if (calificacion === 0) return alert('Por favor selecciona una calificación');
    if (!comentario.trim()) return alert('Por favor escribe un comentario');

    setPublicando(true);
    setTimeout(() => {
      alert('¡Reseña publicada exitosamente!');
      setCalificacion(0);
      setComentario('');
      setPublicando(false);
    }, 2000);
  };

  return (
    <div className="contenedor-producto">
      <div className="seccion-producto">
        <div className="imagenes-producto">
          <div className="imagen-principal">📷</div>
          <div className="miniaturas">
            <div className="miniatura"></div>
            <div className="miniatura"></div>
          </div>
        </div>

        <div className="informacion-producto">
          <h1 className="titulo-producto">Collar de Plata Artesanal</h1>

          <div className="calificacion">
            <div className="estrellas">
              {[1, 2, 3, 4, 5].map((n) => (
                <span
                  key={n}
                  className={`estrella ${n <= 3 ? '' : 'vacia'}`}
                >★</span>
              ))}
            </div>
            <span className="cantidad-resenas">(24 reseñas)</span>
          </div>

          <div className="precio">$45.000</div>
          <div className="stock">📦 Stock disponible: 8 unidades</div>

          <div className="creador">
            <div className="encabezado-creador">Creado por:</div>
            <div className="info-creador">
              <div className="avatar-creador">MG</div>
              <div>
                <h3>María González</h3>
                <p>Artesana especializada en joyería de plata con técnicas tradicionales colombianas.</p>
              </div>
            </div>
            <button className="btn-perfil">Ver Perfil del Artesano</button>
          </div>

          <div className="acciones">
            <button className="btn-carrito">🛒 Añadir al Carrito</button>
            <button className="btn-favorito">♡ Añadir a Favoritos</button>
          </div>
        </div>
      </div>

      <div className="resenas">
        <h2 className="titulo-resenas">Reseñas de Clientes (3)</h2>

        <div className="resena">
          <div className="encabezado-resena">
            <span className="nombre-resenante">Laura Pérez</span>
            <span className="fecha-resena">15 de Noviembre, 2024</span>
          </div>
          <div className="estrellas">★★★★★</div>
          <p>Absolutamente hermoso. La calidad es excepcional y se nota el trabajo artesanal.</p>
        </div>

        <div className="resena">
          <div className="encabezado-resena">
            <span className="nombre-resenante">Roberto Silva</span>
            <span className="fecha-resena">10 de Noviembre, 2024</span>
          </div>
          <div className="estrellas">★★★★★</div>
          <p>Compré este collar para mi esposa y quedó encantada.</p>
        </div>

        <div className="resena">
          <div className="encabezado-resena">
            <span className="nombre-resenante">Carmen Rodríguez</span>
            <span className="fecha-resena">5 de Noviembre, 2024</span>
          </div>
          <div className="estrellas">★★★★☆</div>
          <p>Muy bonito collar, aunque tardó en llegar. Pero vale la pena la espera.</p>
        </div>
      </div>

      <div className="dejar-resena">
        <h2 className="titulo-resena">Deja tu Reseña</h2>
        <p>Solo los usuarios que han comprado este producto pueden dejar reseñas</p>

        <label>Tu Calificación *</label>
        <div className="estrellas-interactivas">
          {[1, 2, 3, 4, 5].map((n) => (
            <span
              key={n}
              className={`estrella-interactiva ${n <= calificacion ? 'activa' : ''}`}
              onClick={() => setCalificacion(n)}
            >★</span>
          ))}
        </div>

        <label>Tu Comentario *</label>
        <textarea
          value={comentario}
          onChange={(e) => setComentario(e.target.value)}
          className="textarea-comentario"
          placeholder="Comparte tu experiencia..."
        ></textarea>

        <button
          onClick={manejarPublicacion}
          disabled={publicando}
          className="btn-publicar"
        >{publicando ? 'Publicando...' : 'Publicar Reseña'}</button>
      </div>
    </div>
  );
};

export default VistaProducto;
